insert into public.reg_area (id, authority, kind, name, parent_id, boundary_geojson, source_url, verified_at, notes) values
  ('wa-ma-5-13-inside', 'wdfw', 'ocean_region', 'Marine Areas 5–13 — Puget Sound, Strait of Juan de Fuca, San Juan Islands, Hood Canal', null, '[[-123.96,49],[-123.1,48.9],[-122.8,48.45],[-122.4,48.9],[-122.3,49.15],[-123.7,49.15],[-123.96,49]]', 'https://wdfw.wa.gov/newsroom/news-release/coastal-recreational-bottomfish-fishery-season-opens-march-14-1', '2026-09-02', 'Envelope over the inside waters. v1 doctrine: rockfish are off-limits in Areas 6-13, barbless hooks required Areas 5-13. Area-by-area pamphlet tables pending.'),
  ('wa-ma-5-10-halibut', 'wdfw', 'ocean_region', 'Puget Sound & Strait of Juan de Fuca halibut (Marine Areas 5–10)', null, null, 'https://wdfw.wa.gov/newsroom/news-release/coastal-recreational-bottomfish-fishery-season-opens-march-14-1', '2026-09-02', 'Halibut subarea per WDFW''s Puget Sound page (2026 quota 80,512 lb). Shares the inside-water envelope; separate id so halibut rules don''t muddy the bottomfish area.'),
  ('wa-yrca', 'wdfw', 'conservation_area', 'Yelloweye Rockfish Conservation Area (C-shaped, off Cape Flattery)', null, '[[-125.3,48.3],[-124.9833,48.3],[-124.9833,48.1833],[-125.1833,48.1833],[-125.1833,48.0667],[-124.9833,48.0667],[-124.9833,48],[-125.3,48],[-125.3,48.3]]', 'https://wdfw.wa.gov/newsroom/news-release/coastal-recreational-bottomfish-fishery-season-opens-march-14-1', '2026-09-02', 'Closed to recreational bottomfish AND halibut fishing. Coordinates verbatim from WDFW''s North Coast page (48-18''N 125-18''W → 48-18''N 124-59''W → 48-11''N 124-59''W → 48-11''N 125-11''W → 48-04''N 125-11''W → 48-04''N 124-59''W → 48-00''N 124-59''W → 48-00''N 125-18''W → back).')
